(8056, 'categories', 'description', 114, 'ru', '<p><iframe src="https://www.youtube.com/embed/5JAXjsrLE24" width="313" height="176" allowfullscreen="allowfullscreen"></iframe></p>\n<p><iframe src="https://www.youtube.com/embed/GIyVqs98sfk?t=1s" width="313" height="176" allowfullscreen="allowfullscreen"></iframe></p>\n<p><iframe src="https://www.youtube.com/embed/eoWa03oAu1Y" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/ozTl1S1Qu1E" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/zCTXggyuAOo?t=1s" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/jPLG0ojcS0o" width="310" height="174" allowfullscreen="allowfullscreen"></iframe><iframe src="https://www.youtube.com/embed/32Y3eurRtY8" width="310" height="174" allowfullscreen="allowfullscreen"></iframe></p>', '2021-03-31 17:59:37', '2024-04-02 18:51:59'),
